from lib import *
S = SS('x92')
steps = [
    step("什么都不写 spring.jpa.open-in-view 时,启动日志会有一条 WARN:「spring.jpa.open-in-view is enabled by default. Therefore, database queries may be performed during view rendering. Explicitly configure spring.jpa.open-in-view to disable this warning」。再看连接被占多久:GET /probe?ms=600 里先 repo.findById(1L)(这是一个很短的事务,没有 @Transactional 的外层),再睡 600 ms。open-in-view 打开时:查库之前活动连接 0,repo.findById 返回之后活动连接 1,再睡 600 ms 之后仍是 1——查询早就结束了,连接却一直被持有到请求结束。显式写 spring.jpa.open-in-view=true 行为一样,只是警告没有了(0 条)。写成 false:查库返回之后活动连接就是 0,睡完仍是 0,连接在事务结束时就还给了池。", t=tl(S(1)), mark=lidx(S(1), '启动日志里的 open-in-view 警告', 'GET /probe?ms=600 → 查库之前活动连接=0,repo.findById 返回之后=1'), done=lidx(S(1), 'open-in-view=false', '显式写'), b=bars([['open-in-view 默认:查库返回之后的活动连接数', 1, '1'], ['open-in-view 默认:睡 600 ms 之后的活动连接数', 1, '1'], ['open-in-view=false:查库返回之后的活动连接数', 0, '0'], ['open-in-view=false:睡 600 ms 之后的活动连接数', 0, '0']], 1, mark=[0, 1], done=[2, 3]), kv=KV([['默认', 'enabled,启动时有 WARN'], ['打开时', '连接持有到请求结束,查询早就结束了'], ['false', '事务一结束连接就还给池'], ['显式写 true', '没有警告,行为不变']], ['打开时'])),
    step("懒加载在控制器里能不能用(控制器方法没有 @Transactional,直接 repo.findById(1L).get().getBooks().size())。open-in-view=true:HTTP 200,books.size()=3,日志里没有异常。open-in-view=false:HTTP 500,服务端日志里是 org.hibernate.LazyInitializationException: Cannot lazily initialize …(没有 Session 了)。也就是说 OSIV 掩盖了「在事务外访问懒加载集合」这类问题;关掉它之后这些地方会立刻暴露——需要在事务内用 join fetch、@EntityGraph 或 DTO 把数据取全。", t=tl(S(2)), mark=lidx(S(2), 'open-in-view=false:GET /lazy', 'LazyInitializationException'), done=lidx(S(2), 'open-in-view=true:GET /lazy'), b=bars([['open-in-view=true:GET /lazy 的 HTTP 状态码', 200, '200'], ['open-in-view=false:GET /lazy 的 HTTP 状态码', 500, '500']], 500, done=[0], mark=[1]), kv=KV([['打开', '控制器里访问懒加载集合不报错'], ['关闭', 'LazyInitializationException,HTTP 500'], ['含义', 'OSIV 掩盖了事务外的懒加载'], ['修法', '事务内 join fetch / @EntityGraph / DTO']], ['关闭'])),
    step("池只有 2 个连接(maximum-pool-size=2,connection-timeout=1000 ms),10 个并发请求,每个请求查库 1 次再睡 300 ms(模拟调用外部服务或渲染),持续 8 秒。open-in-view=true:成功 60 个(7.5 个/秒),失败 17 个,全部是 HTTP 500;成功请求的延迟 p50 是 1225 ms、p99 是 1267 ms;服务端日志里是「HikariPool-1 - Connection is not available, request timed out after 1005ms (total=2, active=2, idle=0, waiting=7)」。open-in-view=false:成功 270 个(33.8 个/秒),失败 0 个,延迟 p50 307 ms、p99 313 ms——连接只在事务里占用,两个连接足够周转。同一个池、同一份代码,仅一个开关,吞吐差了约 4.5 倍(算出来的比值),还从 17 个失败变成 0 个。", t=tl(S(3)), mark=lidx(S(3), 'open-in-view=true:成功', 'Connection is not available'), done=lidx(S(3), 'open-in-view=false:成功'), b=bars([['open-in-view=true:成功请求数', 60, '60'], ['open-in-view=true:失败请求数', 17, '17'], ['open-in-view=false:成功请求数', 270, '270'], ['open-in-view=false:失败请求数', 0, '0']], 270, mark=[0, 1], done=[2, 3]), kv=KV([['打开', '7.5 个/秒,17 个 500,p50 1225 ms'], ['关闭', '33.8 个/秒,0 个失败,p50 307 ms'], ['池', '2 个连接,10 个并发'], ['日志', 'Connection is not available, request timed out']], ['关闭'])),
]
A = mkartx('x92', 92, 'Spring,Data,JPA,Open-In-View,HikariCP,连接池,真实验证,动画演示',
    '实测 Spring Boot 4.0.8 的 spring.jpa.open-in-view:默认打开并在启动时给出 WARN;打开时数据库连接从第一次查询一直被持有到请求结束(查库返回之后、睡 600 ms 之后活动连接都是 1);关闭后懒加载会在事务外抛 LazyInitializationException;池只有 2 个连接时,打开比关闭的吞吐低约 4.5 倍并出现 17 个超时 500。',
    '启动日志里的 open-in-view 警告到底在警告什么?为什么「查询早就结束了」连接还没还?关了会出什么问题?连接池小的时候它会把吞吐拖低多少?这篇在 Spring Boot 4.0.8、HikariCP、MySQL 上用 2 个连接的池实测。',
    [('1 → 0', '查库返回之后活动连接数:open-in-view 默认是 1,关闭后是 0'), ('60 vs 270', '2 个连接、10 个并发、8 秒内的成功请求数:open-in-view 默认与关闭'), ('LazyInitializationException', '关闭 open-in-view 之后,控制器里访问懒加载集合会抛这个异常')],
    [('连接被占多久', '<p>打开时连接从第一次查询持有到请求结束;关闭后事务一结束就还给池。</p>'),
     ('懒加载', '<p>打开时控制器里能访问懒加载集合;关闭后抛 LazyInitializationException。</p>'),
     ('对吞吐的影响', '<p>池小时打开会让连接成为瓶颈:吞吐低约 4.5 倍,还有 HTTP 500。</p>')],
    steps,
    [ENV_X + '(Hibernate 7、HikariCP 随 spring-boot-starter-data-jpa;MySQL 是本机自己起的 26.7.0 实例)。HikariCP maximum-pool-size=2、minimum-idle=2、connection-timeout=1000 ms,其余默认;活动连接数取自 HikariPoolMXBean.getActiveConnections();压测用 10 个 Python 线程循环请求 8 秒,每个请求 repo.findById(1L) 之后 Thread.sleep(300 ms);Tomcat 线程池为默认值',
     '没有验证:池更大、请求更慢时的临界点;外层带 @Transactional 的情形下(连接本来就占用到事务结束);JTA;读写分离或多数据源下 OSIV 对多个 EntityManager 的影响;Spring Data 的 @Transactional(readOnly) 对连接释放时机的影响;连接被持有的具体机制(Hibernate 的 connection handling mode,我只观察到结果);HTTP 500 在 connection-timeout 更长时的表现'],
    'Open-In-View')
